fn is_space(c: Int) -> Bool {
  return c == 32 or c == 9 or c == 10 or c == 13
}

fn is_digit(c: Int) -> Bool {
  return c >= 48 and c <= 57
}

fn is_alpha(c: Int) -> Bool {
  return (c >= 65 and c <= 90) or (c >= 97 and c <= 122) or c == 95
}

// + - * / < > = ( ) { } , ;
fn is_single(c: Int) -> Bool {
  return c == 43 or c == 45 or c == 42 or c == 47 or c == 60 or c == 62 or c == 61 or c == 40 or c == 41 or c == 123 or c == 125 or c == 44 or c == 59
}

pub fn tokens(src: Str) -> Result[List[Str], Str] {
  let cs = src.chars()
  let ks = src.codes()
  let n = cs.len()
  var out: List[Str] = []
  var i = 0
  while i < n {
    let c = ks.get_or(i, 0)
    if is_space(c) {
      i = i + 1
    } else if is_alpha(c) {
      var j = i + 1
      while j < n and (is_alpha(ks.get_or(j, 0)) or is_digit(ks.get_or(j, 0))) {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if is_digit(c) {
      var j = i + 1
      while j < n and is_digit(ks.get_or(j, 0)) {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if c == 34 {
      var j = i + 1
      var closed = false
      while j < n and closed == false {
        let d = ks.get_or(j, 0)
        if d == 34 {
          closed = true
        } else if d == 92 {
          j = j + 2
        } else {
          j = j + 1
        }
      }
      if closed == false {
        return Err("unterminated string")
      }
      out = out.push(cs.slice(i, j + 1).join(""))
      i = j + 1
    } else {
      let d = ks.get_or(i + 1, 0)
      let two = (c == 61 and d == 61) or (c == 33 and d == 61) or (c == 60 and d == 61) or (c == 62 and d == 61) or (c == 45 and d == 62)
      if two and i + 1 < n {
        out = out.push(cs.slice(i, i + 2).join(""))
        i = i + 2
      } else if is_single(c) {
        out = out.push(cs.get_or(i, ""))
        i = i + 1
      } else {
        return Err("unexpected " + cs.get_or(i, ""))
      }
    }
  }
  return Ok(out)
}
